        ["확인하지 못함 (모드 정보의 주소를 확인해 주세요): {0}"] = ("Could not check (check the address in the mod info): {0}", "无法检查（请检查模组信息中的地址）：{0}", "確認できません（Mod 情報のアドレスを確認してください）: {0}"),
        ["새 버전 {0}개 있음"] = ("{0} new version(s) available", "有 {0} 个新版本", "新しいバージョンが {0} 個あります"),
