        ["{0} 중..."] = ("{0} in progress...", "正在{0}...", "{0}中..."),
        ["{0}{1} {2} 완료"] = ("{2} done: {0}{1}", "{0}{1} {2}完成", "{0}{1} の{2}完了"),
