        ["덮어쓰기 ({0} 모드와 충돌)"] = ("Overwrite (conflicts with {0})", "覆盖（与 {0} 模组冲突）", "上書き（{0} と競合）"),
        ["수정된 파일 덮어쓰기 (백업)"] = ("Overwrite changed file (backed up)", "覆盖已修改的文件（已备份）", "変更されたファイルを上書き（バックアップ）"),
