        ["전체 선택"] = ("Select all", "全选", "すべて選択"),
        ["전체 해제"] = ("Clear all", "全部取消", "すべて解除"),
        ["{0} / {1}개"] = ("{0} / {1}", "{0} / {1} 个", "{0} / {1} 個"),
        ["{0}개"] = ("{0}", "{0} 个", "{0} 個"),
        ["설치할 파일 {0} / {1}개"] = ("Files to install: {0} / {1}", "要安装的文件 {0} / {1} 个", "インストールするファイル {0} / {1} 個"),
        ["Nexus 응답 오류 ({0}). 잠시 후 다시 시도해 주세요."] = ("Nexus response error ({0}). Please try again later.", "Nexus 响应错误（{0}）。请稍后重试。", "Nexus の応答エラー ({0})。しばらくしてからもう一度お試しください。"),
        ["Nexus가 요청을 처리하지 못했습니다: "] = ("Nexus could not process the request: ", "Nexus 无法处理请求：", "Nexus がリクエストを処理できませんでした:"),
        ["응답 오류 ({0}). 잠시 후 다시 시도해 주세요."] = ("Response error ({0}). Please try again later.", "响应错误（{0}）。请稍后重试。", "応答エラー ({0})。しばらくしてからもう一度お試しください。"),
        ["설치된 버전의 파일은 삭제할 수 없습니다. 먼저 모드를 제거하거나 다른 버전으로 업데이트해 주세요.\n{0}"] = ("The installed version's file cannot be deleted. Remove the mod or update it to another version first.\n{0}", "无法删除已安装版本的文件。请先移除该模组或更新到其他版本。\n{0}", "インストール済みバージョンのファイルは削除できません。先に Mod を削除するか、別のバージョンに更新してください。\n{0}"),
        ["파일을 휴지통으로 보내지 못했습니다: {0}"] = ("Could not send the file to the Recycle Bin: {0}", "无法将文件移到回收站：{0}", "ファイルをごみ箱に送れませんでした: {0}"),
        ["zip, rar, 7z 파일만 추가할 수 있습니다: {0}"] = ("Only zip, rar and 7z files can be added: {0}", "只能添加 zip、rar、7z 文件：{0}", "追加できるのは zip・rar・7z ファイルだけです: {0}"),
        ["올바른 zip 파일이 아닙니다: {0}"] = ("Not a valid zip file: {0}", "不是有效的 zip 文件：{0}", "正しい zip ファイルではありません: {0}"),
        ["MOD 폴더에 이름이 같은 다른 파일이 이미 있습니다: {0}"] = ("The MOD folder already has a different file with the same name: {0}", "MOD 文件夹中已有同名的其他文件：{0}", "MOD フォルダーに同じ名前の別のファイルがすでにあります: {0}"),
        ["모드 파일을 .manager\\archives로 옮기는 중... {0}/{1}"] = ("Moving mod files into .manager\\archives... {0}/{1}", "正在将模组文件移到 .manager\\archives... {0}/{1}", "Mod ファイルを .manager\\archives に移動中... {0}/{1}"),
        ["압축 형식 바꾸는 중... {0}/{1}"] = ("Converting the archive... {0}/{1}", "正在转换压缩格式... {0}/{1}", "圧縮形式を変換中... {0}/{1}"),
        ["압축 파일을 읽지 못했습니다: {0}\n{1}"] = ("Could not read the archive: {0}\n{1}", "无法读取压缩包：{0}\n{1}", "圧縮ファイルを読み込めませんでした: {0}\n{1}"),
        ["이후 설치로 덮어씀"] = ("Overwritten by a later install", "被之后的安装覆盖", "後のインストールで上書き"),
        ["새 버전에 없어 제거됨"] = ("Removed, not in the new version", "新版本中没有，已移除", "新しいバージョンにないため削除"),
        ["정상"] = ("OK", "正常", "正常"),
        ["미분류"] = ("Uncategorized", "未分类", "未分類"),
        ["전체"] = ("All", "全部", "すべて"),
        ["이름을 입력해 주세요."] = ("Enter a name.", "请输入名称。", "名前を入力してください。"),
        ["'{0}'은(는) 이미 쓰고 있는 이름이라 사용할 수 없습니다."] = ("'{0}' is a name already in use and cannot be used.", "“{0}”是已在使用的名称，不能使用。", "「{0}」はすでに使われている名前のため使用できません。"),
        ["'{0}' 카테고리가 이미 있습니다."] = ("The category '{0}' already exists.", "分类“{0}”已存在。", "カテゴリー「{0}」はすでにあります。"),
        ["압축 파일 확인 중... {0}/{1}"] = ("Checking the archive... {0}/{1}", "正在检查压缩包... {0}/{1}", "圧縮ファイルを確認中... {0}/{1}"),
        ["폴더가 들어갈 자리에 같은 이름의 파일이 있습니다: {0}"] = ("A file with the same name is where a folder must go: {0}", "文件夹要放置的位置已有同名文件：{0}", "フォルダーが入る場所に同じ名前のファイルがあります: {0}"),
        ["압축 안에 같은 경로의 파일이 중복됩니다: {0}"] = ("The archive has the same path twice: {0}", "压缩包中有重复路径的文件：{0}", "圧縮ファイル内に同じパスのファイルが重複しています: {0}"),
        ["파일이 들어갈 자리에 같은 이름의 폴더가 있습니다: {0}"] = ("A folder with the same name is where a file must go: {0}", "文件要放置的位置已有同名文件夹：{0}", "ファイルが入る場所に同じ名前のフォルダーがあります: {0}"),
        ["Mods Menu용 파일 {0}개를 모드 로더 폴더로 옮겨 설치합니다. Mods Menu의 설정 화면은 쓸 수 없고, 메뉴 기능이 필요한 모드는 동작하지 않을 수 있습니다."] = ("{0} Mods Menu file(s) will be moved into the mod loader folder. Mods Menu's settings screen will not be available, and mods that need menu features may not work.", "将把 {0} 个 Mods Menu 用的文件移到模组加载器文件夹安装。无法使用 Mods Menu 的设置界面，需要菜单功能的模组可能无法运行。", "Mods Menu 用のファイル {0} 個を Mod ローダーのフォルダーに移してインストールします。Mods Menu の設定画面は使えず、メニュー機能が必要な Mod は動作しない場合があります。"),
        ["UE4SS 파일 {0}개를 게임 실행 파일(PBZ.exe) 옆인 platform/steam에 설치합니다."] = ("{0} UE4SS file(s) will be installed in platform/steam, beside the game's PBZ.exe.", "将把 {0} 个 UE4SS 文件安装到游戏程序 (PBZ.exe) 旁边的 platform/steam。", "UE4SS のファイル {0} 個をゲームの実行ファイル (PBZ.exe) の隣、platform/steam にインストールします。"),
        ["모드 로더용 복사본 {0}개는 설치하지 않습니다. 같은 모드가 Mods Menu용으로도 들어 있습니다."] = ("{0} copy(ies) for the mod loader will not be installed. The archive has the same mod for Mods Menu too.", "不会安装 {0} 个模组加载器用的副本。压缩包中也包含同一模组的 Mods Menu 版本。", "Mod ローダー用のコピー {0} 個はインストールしません。同じ Mod が Mods Menu 用にも入っています。"),
        ["Mods Menu용 복사본 {0}개는 설치하지 않습니다. 같은 모드가 모드 로더용으로도 들어 있습니다."] = ("{0} copy(ies) for Mods Menu will not be installed. The archive has the same mod for the mod loader too.", "不会安装 {0} 个 Mods Menu 用的副本。压缩包中也包含同一模组的模组加载器版本。", "Mods Menu 用のコピー {0} 個はインストールしません。同じ Mod が Mod ローダー用にも入っています。"),
        ["PBZModLoader와 Mods Menu가 함께 설치됩니다. 둘 다 두어도 됩니다. 보통 Mods Menu가 먼저 시작해 PBZModLoader 폴더의 모드까지 함께 실행하고, PBZModLoader가 먼저 시작하면 Mods Menu는 꺼집니다."] = ("PBZModLoader and Mods Menu will both be installed. Both may stay: Mods Menu normally starts first and also runs the mods in PBZModLoader's folder; if PBZModLoader starts first, Mods Menu stays off.", "PBZModLoader 和 Mods Menu 将同时安装。两者可以共存：通常 Mods Menu 先启动并同时运行 PBZModLoader 文件夹中的模组；若 PBZModLoader 先启动，Mods Menu 将不启用。", "PBZModLoader と Mods Menu が両方インストールされます。両方入れておけます。通常は Mods Menu が先に起動して PBZModLoader のフォルダーの Mod も実行し、PBZModLoader が先に起動すると Mods Menu はオフのままになります。"),
        ["pak 파일 {0}개를 {1}에 설치합니다."] = ("{0} pak file(s) will be installed in {1}.", "将把 {0} 个 pak 文件安装到 {1}。", "pak ファイル {0} 個を {1} にインストールします。"),
        ["UE4SS 모드 {0}을(를) {1}에 설치합니다."] = ("UE4SS mod {0} will be installed in {1}.", "将把 UE4SS 模组 {0} 安装到 {1}。", "UE4SS の Mod {0} を {1} にインストールします。"),
        ["UE4SS가 설치되어 있지 않습니다. UE4SS를 먼저 설치해야 이 모드가 동작합니다."] = ("UE4SS is not installed. Install UE4SS first for this mod to work.", "未安装 UE4SS。必须先安装 UE4SS，此模组才能运行。", "UE4SS がインストールされていません。この Mod を動かすには先に UE4SS をインストールしてください。"),
        ["파일 {0}개를 게임 실행 파일(PBZ.exe) 옆인 platform/steam에 설치합니다."] = ("{0} file(s) will be installed in platform/steam, beside the game's PBZ.exe.", "将把 {0} 个文件安装到游戏程序 (PBZ.exe) 旁边的 platform/steam。", "ファイル {0} 個をゲームの実行ファイル (PBZ.exe) の隣、platform/steam にインストールします。"),
        ["설치하지 않는 파일: "] = ("Not installed: ", "不安装的文件：", "インストールしないファイル:"),
        ["고르지 않은 옵션 {0}개"] = ("{0} unchosen option file(s)", "未选的选项 {0} 个", "選ばなかったオプション {0} 個"),
        ["설명 그림 {0}개"] = ("{0} description picture(s)", "说明图片 {0} 张", "説明画像 {0} 個"),
        ["설명서 {0}개 (모드 정보의 [설명서 보기]로 볼 수 있음)"] = ("{0} readme files (read them with [Readme] in the mod info)", "说明文件 {0} 个（可在模组信息中用 [查看说明] 阅读）", "説明書 {0} 個（Mod 情報の [説明書を見る] で読めます）"),
        ["디스크 여유 공간이 부족합니다."] = ("Not enough free disk space.", "磁盘可用空间不足。", "ディスクの空き容量が足りません。"),
        ["압축의 최상위 폴더가 게임 폴더 구조와 맞지 않습니다. 폴더가 한 겹 더 감싸져 있을 수 있습니다."] = ("The archive's top folders do not match the game folder layout. It may be wrapped in one more folder.", "压缩包的顶层文件夹与游戏文件夹结构不符。可能多包了一层文件夹。", "圧縮ファイルの最上位フォルダーがゲームフォルダーの構成と合いません。フォルダーがもう 1 階層包まれている可能性があります。"),
        ["옵션 구성이 바뀌어 이전에 고른 옵션을 이어받을 수 없습니다."] = ("The options were reorganized, so the options you chose before cannot carry over.", "选项构成已改变，无法沿用之前选择的选项。", "オプション構成が変わったため、以前選んだオプションを引き継げません。"),
        ["설치 위치가 바뀌어 이전 버전 파일 {0}개 중 {1}개가 새 버전에 없습니다."] = ("Install locations changed: {1} of the previous version's {0} files are not in the new version.", "安装位置已改变：旧版本的 {0} 个文件中有 {1} 个不在新版本中。", "インストール先が変わり、以前のバージョンのファイル {0} 個のうち {1} 個が新しいバージョンにありません。"),
        ["#{0} 작업이 중단된 상태입니다. 먼저 되돌려 주세요."] = ("Operation #{0} was interrupted. Undo it first.", "#{0} 操作处于中断状态。请先撤销。", "#{0} の作業が中断されたままです。先に元に戻してください。"),
        ["미리보기 이후 게임 폴더가 변경되었습니다. 다시 시도해 주세요."] = ("The game folder changed after the preview. Please try again.", "预览后游戏文件夹发生了变化。请重试。", "プレビューの後にゲームフォルダーが変更されました。もう一度お試しください。"),
        ["적용할 변경 사항이 없습니다."] = ("There are no changes to apply.", "没有要应用的更改。", "適用する変更はありません。"),
        ["백업 중..."] = ("Backing up...", "正在备份...", "バックアップ中..."),
        ["백업 중... {0}/{1}"] = ("Backing up... {0}/{1}", "正在备份... {0}/{1}", "バックアップ中... {0}/{1}"),
        ["백업 검증 실패: {0}"] = ("Backup check failed: {0}", "备份校验失败：{0}", "バックアップの検証に失敗: {0}"),
        ["파일 복사 중..."] = ("Copying files...", "正在复制文件...", "ファイルをコピー中..."),
        ["파일 복사 중... {0}/{1}"] = ("Copying files... {0}/{1}", "正在复制文件... {0}/{1}", "ファイルをコピー中... {0}/{1}"),
        ["압축 해제 검증 실패: {0}"] = ("Extraction check failed: {0}", "解压校验失败：{0}", "展開の検証に失敗: {0}"),
        ["{0} #{1} {2} (추가 {3}, 덮어씀 {4}, 옛 파일 제거 {5})"] = ("{0} #{1} {2} (added {3}, overwritten {4}, old files removed {5})", "{0} #{1} {2}（新增 {3}，覆盖 {4}，移除旧文件 {5}）", "{0} #{1} {2}（追加 {3}、上書き {4}、旧ファイル削除 {5}）"),
        ["설치 실패 #{0} {1}: {2}"] = ("Install failed #{0} {1}: {2}", "安装失败 #{0} {1}：{2}", "インストール失敗 #{0} {1}: {2}"),
        ["설치 실패: {0}\n자동 복구도 실패했습니다: {1}\n다시 실행하면 복구를 재시도합니다."] = ("Install failed: {0}\nAutomatic recovery failed too: {1}\nRecovery is tried again on the next start.", "安装失败：{0}\n自动恢复也失败了：{1}\n下次运行时将重试恢复。", "インストール失敗: {0}\n自動復旧にも失敗しました: {1}\n次回起動時に復旧を再試行します。"),
        ["설치 실패, 원래 상태로 복구했습니다.\n{0}"] = ("Install failed; the original state was restored.\n{0}", "安装失败，已恢复到原来的状态。\n{0}", "インストールに失敗したため、元の状態に戻しました。\n{0}"),
        ["#{0} 기록이 없습니다."] = ("No record #{0}.", "没有 #{0} 记录。", "#{0} の記録がありません。"),
        ["#{0} 되돌리는 중..."] = ("Undoing #{0}...", "正在撤销 #{0}...", "#{0} を元に戻しています..."),
        ["#{0} 제거 중..."] = ("Removing #{0}...", "正在移除 #{0}...", "#{0} を削除中..."),
        ["되돌림 #{0} {1}"] = ("Undone #{0} {1}", "已撤销 #{0} {1}", "元に戻した #{0} {1}"),
        [" (보관: {0})"] = (" (kept: {0})", "（保留：{0}）", "（保管: {0}）"),
        ["백업 파일이 없습니다: {0}"] = ("Backup file missing: {0}", "备份文件不存在：{0}", "バックアップファイルがありません: {0}"),
        ["백업 파일이 손상되었습니다: {0}"] = ("Backup file is damaged: {0}", "备份文件已损坏：{0}", "バックアップファイルが破損しています: {0}"),
        ["허용되지 않는 압축 경로: {0}"] = ("Path not allowed in the archive: {0}", "不允许的压缩包路径：{0}", "許可されていない圧縮パス: {0}"),
        ["매니저 폴더에는 설치할 수 없습니다: {0}"] = ("Cannot install into the manager's folder: {0}", "不能安装到管理器文件夹：{0}", "マネージャーのフォルダーにはインストールできません: {0}"),
        ["게임이 실행 중입니다. 게임을 종료한 뒤 다시 시도해 주세요."] = ("The game is running. Close the game and try again.", "游戏正在运行。请关闭游戏后重试。", "ゲームが実行中です。ゲームを終了してからもう一度お試しください。"),
        ["PBZ Mod Manager 모드 목록 ({0}개)"] = ("PBZ Mod Manager mod list ({0} mods)", "PBZ Mod Manager 模组列表（{0} 个）", "PBZ Mod Manager Mod 一覧（{0} 個）"),
        ["PBZ Mod Manager 모드 목록이 아닙니다. 공유받은 파일이나 글 전체를 그대로 넣어 주세요."] = ("This is not a PBZ Mod Manager mod list. Use the shared file, or paste the whole shared text as it is.", "这不是 PBZ Mod Manager 模组列表。请使用分享的文件，或原样粘贴分享的全部文字。", "PBZ Mod Manager の Mod 一覧ではありません。共有されたファイルか、共有された文章全体をそのまま入れてください。"),
